svg.script:
test(() => {
  const rect = document.getElementById("rounded");
  assert_false(rect.isPointInFill({x: 11, y: 21}));
  assert_true(rect.isPointInFill({x: 60, y: 40}));
  const box = rect.getBBox();
  assert_equals(box.x, 10);
  assert_equals(box.y, 20);
  assert_equals(box.width, 100);
  assert_equals(box.height, 40);
}, "Elliptical rounded corners affect fill but preserve the bounding box");

test(() => {
  const rect = document.getElementById("rounded");
  const start = rect.getPointAtLength(0);
  assert_equals(start.x, 30);
  assert_equals(start.y, 20);
  const arcs = document.getElementById("arcs").getTotalLength();
  assert_approx_equals(rect.getTotalLength(), 160 + arcs, 0.2);
}, "Rounded rectangle path begins after rx and includes four elliptical arcs");

test(() => {
  const rect = document.getElementById("css");
  assert_equals(rect.getPointAtLength(0).x, 30);
  assert_false(rect.isPointInFill({x: 11, y: 21}));
}, "CSS rx and ry override rectangle radius presentation attributes");

test(() => {
  const rect = document.getElementById("auto");
  assert_equals(rect.getPointAtLength(0).x, 20);
  assert_false(rect.isPointInFill({x: 1, y: 1}));
}, "An auto radius takes the other radius before both are clamped to half size");

test(() => {
  const rect = document.getElementById("percentage");
  assert_equals(rect.getPointAtLength(0).x, 20);
  assert_false(rect.isPointInFill({x: 1, y: 1}));
}, "Rectangle radius percentages resolve against its own width and height");

test(() => {
  const rect = document.getElementById("dynamic");
  assert_true(rect.isPointInFill({x: 1, y: 1}));
  rect.style.rx = "10px";
  rect.style.ry = "5px";
  assert_false(rect.isPointInFill({x: 1, y: 1}));
  assert_equals(rect.getPointAtLength(0).x, 10);
}, "Changing CSS radii updates rectangle geometry DOM methods");

test(() => {
  const rect = document.getElementById("zero");
  assert_true(rect.isPointInFill({x: 1, y: 1}));
  assert_equals(rect.getPointAtLength(0).x, 0);
}, "An explicit zero radius leaves rectangle corners square");
